1	// Deploy WIN-BACK — re-engagement sweep (worker task).
2	//
3	// Registered on the worker loop (worker/index.ts) and gated HARD behind the
4	// `deploy_winback_enabled` master kill-switch (env `DEPLOY_WINBACK_ENABLED` also
5	// enables it). While that flag is false this sweep returns immediately and
6	// NOTHING is queried, rendered, or sent — so shipping the code mails no one until
7	// a human turns it on.
8	//
9	// What it does when enabled: finds signed-in users who STARTED the deploy wizard
10	// (DeployFunnelEvent type='step') and abandoned it — their most recent step is
11	// older than a short cooldown (don't email mid-session) but newer than a max age
12	// (stay timely) — excludes anyone who finished, already owns a server, is
13	// unverified/opted-out, or has already had this email, then sends each a branded
14	// win-back offering a first-month discount coupon. Modeled on worker/marketing.ts
15	// (marketingDiscoverySweep) and worker/coldemail.ts (coldEmailSendSweep): same
16	// flag gate, per-item try/catch, send cap, and count logging.
17	//
18	// COMPLIANCE: the send uses the PRODUCT/marketing NotifyKind (`product_news`), so
19	// `sendMail` → `mayDeliverTo` enforces the customer's marketing opt-out, and the
20	// shared email shell carries the unsubscribe footer. Suppression is enforced the
21	// same central way every other send is.
22	
23	import { db } from "../lib/db";
24	import { getSettingBool, getSettingInt } from "../lib/settings";
25	import { sendMail, emails } from "../lib/mailer";
26	import { mayDeliverTo } from "../lib/prefs";
27	import { appUrl } from "../lib/email-render";
28	import { marketingUnsubUrl } from "../lib/marketing-unsub";
29	
30	/**
31	 * The campaign coupon code — ONE constant. The owner creates a matching coupon in
32	 * the Coupons engine (any-plan, first-month, this percent). Nothing here mints it;
33	 * the email just presents the code.
34	 */
35	export const WINBACK_COUPON_CODE = "COMEBACK50";
36	/** Percent off the first month the campaign advertises (must match the coupon). */
37	export const WINBACK_PERCENT_OFF = 50;
38	
39	/** EmailLog.template tag used both to WRITE the send and to DEDUPE against it. */
40	const WINBACK_TEMPLATE_TAG = "deploy_winback";
41	
42	/**
43	 * Defaults for the two configurable window knobs (Setting keys below). Both are
44	 * read at sweep time so the owner can retune from the admin panel without a deploy.
45	 *
46	 *  COOLDOWN (`deploy_winback_delay_minutes`) — a user whose latest wizard step is
47	 *  more recent than (now − delay) is treated as still mid-session and NOT emailed.
48	 *  MAX_AGE  (`deploy_winback_max_age_days`)  — a user whose latest step is older
49	 *  than (now − max age) is too cold to be timely and is skipped.
50	 */
51	const DEFAULT_DELAY_MINUTES = 30;
52	const DEFAULT_MAX_AGE_DAYS = 30;
53	
54	/** Hard cap on sends per sweep run — bounds a burst if a backlog builds up. */
55	const MAX_SENDS_PER_SWEEP = 25;
56	
57	/** Gentle pacing between sends so a run never blasts the SMTP relay. */
58	const SEND_GAP_MS = 1200;
59	const sleep = (ms: number) => new Promise((r) => setTimeout(r, ms));
60	
61	/**
62	 * A friendly, non-stale expiry label ("Sep 30"): the last day of NEXT month. The
63	 * owner sets the real coupon expiry ~here; the copy stays accurate week to week
64	 * rather than hardcoding a date that goes stale.
65	 */
66	function winbackExpiresLabel(now = new Date()): string {
67	  // Day 0 of month+2 == last day of month+1.
68	  const lastDayNextMonth = new Date(Date.UTC(now.getUTCFullYear(), now.getUTCMonth() + 2, 0));
69	  return lastDayNextMonth.toLocaleDateString("en-US", { month: "short", day: "numeric", timeZone: "UTC" });
70	}
71	
72	/**
73	 * The win-back sweep. GATED by `deploy_winback_enabled` (or env
74	 * `DEPLOY_WINBACK_ENABLED`) — the single line that keeps everything below inert
75	 * until a human enables it on prod.
76	 */
77	export async function deployWinbackSweep(): Promise<void> {
78	  // ===== MASTER KILL-SWITCH (first line) =====
79	  const envOn = process.env.DEPLOY_WINBACK_ENABLED === "true";
80	  if (!envOn && !(await getSettingBool("deploy_winback_enabled", false))) return;
81	
82	  const now = Date.now();
83	
84	  // Configurable window (retunable from the admin panel; no deploy needed).
85	  const delayMinutes = await getSettingInt("deploy_winback_delay_minutes", DEFAULT_DELAY_MINUTES);
86	  let maxAgeDays = await getSettingInt("deploy_winback_max_age_days", DEFAULT_MAX_AGE_DAYS);
87	  const delayMs = Math.max(1, delayMinutes) * 60_000;
88	  // GUARD: the max age must exceed the delay, or the window collapses to empty. A
89	  // stored value that violates that (e.g. a mis-save) falls back to the default so
90	  // the sweep still has a usable window rather than silently selecting no one.
91	  if (maxAgeDays * 24 * 60 * 60_000 <= delayMs) maxAgeDays = DEFAULT_MAX_AGE_DAYS;
92	  const maxAgeMs = maxAgeDays * 24 * 60 * 60_000;
93	
94	  const cooldownCutoff = new Date(now - delayMs); // latest step must be BEFORE this
95	  const maxAgeCutoff = new Date(now - maxAgeMs); // latest step must be AFTER this
96	
97	  // CANDIDATES: for each user who has any wizard STEP event, the timestamp of
98	  // their most recent step. Grouping (not a raw findMany) is what lets us test the
99	  // LATEST step against the window — so a user still clicking through the wizard
100	  // right now (a recent step) is never selected even if they also have an older one.
101	  const grouped = await db.deployFunnelEvent
102	    .groupBy({
103	      by: ["userId"],
104	      where: { type: "step", userId: { not: null } },
105	      _max: { createdAt: true },
106	      orderBy: { _max: { createdAt: "desc" } },
107	    })
108	    // Table not present on this environment yet — no-op (mirrors the other sweeps).
109	    .catch(() => null);
110	  if (!grouped) return;
111	
112	  const candidateIds: string[] = [];
113	  for (const g of grouped) {
114	    const last = g._max.createdAt;
115	    if (g.userId && last && last < cooldownCutoff && last > maxAgeCutoff) {
116	      candidateIds.push(g.userId);
117	    }
118	  }
119	  if (candidateIds.length === 0) return;
120	
121	  // ---- Batched exclusions (cheap set lookups, no N+1) ----------------------
122	  // Finished the wizard at least once → converted intent, never win-back.
123	  const completed = await db.deployFunnelEvent.findMany({
124	    where: { userId: { in: candidateIds }, type: "complete" },
125	    distinct: ["userId"],
126	    select: { userId: true },
127	  });
128	  const completedIds = new Set(completed.map((c) => c.userId));
129	
130	  // Already sent this win-back → dedupe. Matches EmailLog rows tagged with our
131	  // template. NOTE: EmailLog is retained ~90 days (lib/email-render
132	  // emailLogRetentionDays), so this is "once per user" in practice bounded to at
133	  // most once per retention window — a user who abandoned again 90+ days later
134	  // (and still hasn't converted) may be re-engaged once more, which is intended.
135	  const alreadySent = await db.emailLog.findMany({
136	    where: { userId: { in: candidateIds }, template: WINBACK_TEMPLATE_TAG, status: "SENT" },
137	    distinct: ["userId"],
138	    select: { userId: true },
139	  });
140	  const alreadySentIds = new Set(alreadySent.map((e) => e.userId).filter((x): x is string => !!x));
141	
142	  // User rows: email + verification + whether they own any server (existing/
143	  // converting customer). _count.servers > 0 excludes them.
144	  const users = await db.user.findMany({
145	    where: { id: { in: candidateIds } },
146	    select: {
147	      id: true,
148	      name: true,
149	      email: true,
150	      emailVerifiedAt: true,
151	      _count: { select: { servers: true } },
152	    },
153	  });
154	  const userById = new Map(users.map((u) => [u.id, u]));
155	
156	  const expiresLabel = winbackExpiresLabel(new Date(now));
157	  const deployUrl = `${appUrl()}/dashboard/deploy`;
158	
159	  let considered = 0;
160	  let sent = 0;
161	  let skipped = 0;
162	  let failed = 0;
163	
164	  for (const userId of candidateIds) {
165	    if (sent >= MAX_SENDS_PER_SWEEP) break;
166	    considered++;
167	
168	    const u = userById.get(userId);
169	    // Exclusions: finished the wizard; owns a server; already emailed; no email;
170	    // email not verified.
171	    if (!u) { skipped++; continue; }
172	    if (completedIds.has(userId)) { skipped++; continue; }
173	    if (u._count.servers > 0) { skipped++; continue; }
174	    if (alreadySentIds.has(userId)) { skipped++; continue; }
175	    if (!u.email) { skipped++; continue; }
176	    if (!u.emailVerifiedAt) { skipped++; continue; }
177	
178	    // Marketing opt-out / suppression. `sendMail` enforces this centrally too, but
179	    // pre-checking lets us skip cleanly (and not attempt a send we'd suppress).
180	    let deliverable = true;
181	    try {
182	      deliverable = await mayDeliverTo(userId, "product_news", "email");
183	    } catch {
184	      deliverable = true; // fail open — mirrors mayDeliverTo's own contract
185	    }
186	    if (!deliverable) { skipped++; continue; }
187	
188	    try {
189	      // Per-recipient one-click marketing unsubscribe (signed token).
190	      const unsubUrl = marketingUnsubUrl(userId);
191	      const built = emails.deployWinback({
192	        name: u.name,
193	        couponCode: WINBACK_COUPON_CODE,
194	        percentOff: WINBACK_PERCENT_OFF,
195	        expiresLabel,
196	        deployUrl,
197	        unsubscribeUrl: unsubUrl, // muted footer link in the body
198	      });
199	      // Marketing kind → opt-outs honoured; template tag → EmailLog dedupe row;
200	      // listUnsubscribeUrl → RFC 8058 List-Unsubscribe headers on this send.
201	      const ok = await sendMail({
202	        to: u.email,
203	        subject: built.subject,
204	        html: built.html,
205	        template: built.template, // "deploy_winback" — the dedupe tag
206	        listUnsubscribeUrl: unsubUrl,
207	        userId,
208	        kind: "product_news",
209	      });
210	      if (ok) sent++;
211	      else failed++;
212	    } catch (e) {
213	      failed++;
214	      console.error(`[winback] send failed for user ${userId}`, e);
215	    }
216	
217	    await sleep(SEND_GAP_MS);
218	  }
219	
220	  if (sent > 0 || failed > 0) {
221	    console.log(
222	      `[winback] sweep complete — considered ${considered}/${candidateIds.length}, sent ${sent}, skipped ${skipped}, failed ${failed}`,
223	    );
224	  }
225	}
