176	      }
177	      // Atomic conditional increment — the global cap gate. Same guard as claimOrderCoupon.
178	      const claim = await tx.coupon.updateMany({
179	        where:
180	          opts.maxRedemptions === null
181	            ? { id: opts.couponId, active: true }
182	            : { id: opts.couponId, active: true, timesRedeemed: { lt: opts.maxRedemptions } },
183	        data: { timesRedeemed: { increment: 1 } },
184	      });
185	      if (claim.count !== 1) return { reserved: false as const, error: "That code has reached its redemption limit." };
