215	 * idempotent (a replayed fulfil, or a race with the sweep, matches zero rows) and
216	 * guarantees we never "confirm" a hold that was already released. `timesRedeemed` is
217	 * NOT touched — it was already incremented at reserve — so there is never a second
218	 * discount or a double count. Returns true when THIS call did the confirming.
219	 */
220	export async function confirmOrderCouponReservation(
221	  tx: Prisma.TransactionClient,
222	  token: string,
223	): Promise<boolean> {
224	  const res = await redemptionDelegate(tx).updateMany({
225	    where: { reservationToken: token, state: COUPON_STATE.RESERVED },
226	    data: { state: COUPON_STATE.CONSUMED, reservedUntil: null },
