258	 * the worker so a dead hold (and its global slot) is reclaimed even if the
259	 * `checkout.session.expired` webhook is not configured or was missed. Each row is handed
260	 * to `releaseOrderCouponReservation` so the delete + `timesRedeemed` decrement stay
261	 * atomic and guarded per coupon. Returns how many were reaped. Bounded per pass.
262	 */
263	export async function sweepExpiredCouponReservations(now = new Date(), limit = 500): Promise<number> {
264	  const dead = await redemptionDelegate(db).findMany({
265	    where: { state: COUPON_STATE.RESERVED, reservedUntil: { lt: now } },
266	    take: limit,
267	  });
268	  let released = 0;
269	  for (const r of dead) {
270	    if (r.reservationToken) {
271	      await releaseOrderCouponReservation(r.reservationToken);
272	      released += 1;
273	    }
274	  }
275	  return released;
276	}
