/**
 * Coupons applied at CHECKOUT of a service (not fungible wallet credit).
 *
 * This is what makes "one free month on the Starter VPS" mean exactly that:
 *  - `serviceKind` + `planSlug` lock the coupon to a product family and/or a
 *    single plan, so it cannot be spent on a bigger plan or a different service;
 *  - `maxTermMonths` caps how many months of the term it may discount, so a
 *    percentage/free coupon cannot be stretched over a 12-month order to hand
 *    someone a year for free.
 *
 * Pure and framework-free so the money maths is unit-tested. The atomic
 * redemption claim (count + per-user + per-IP guards) lives in lib/order.ts.
 */

export type CouponServiceKind = "ANY" | "VPS" | "GAME";
export type CouponKind = "PERCENT" | "FIXED_CENTS" | "CREDIT_CENTS";

/** The coupon fields the order maths needs. */
export type OrderCoupon = {
  kind: CouponKind;
  value: number;
  serviceKind: CouponServiceKind;
  planSlug: string | null;
  maxTermMonths: number | null;
  active: boolean;
  expiresAt: Date | null;
  maxRedemptions: number | null;
  timesRedeemed: number;
  minAmountCents: number | null;
};

export type OrderContext = {
  /** "VPS" or "GAME" — what the customer is buying. */
  serviceKind: "VPS" | "GAME";
  /** The plan's slug, matched against `coupon.planSlug`. */
  planSlug: string;
  /** The plan's REGULAR monthly price (before term/seasonal discounts), cents. */
  planMonthlyCents: number;
  /** The term the customer chose, in months. */
  termMonths: number;
  /** What the plan portion of the order actually costs (first-term, cents). */
  planChargeCents: number;
};

/** Does this coupon apply to the thing being bought? */
export function couponMatchesService(coupon: Pick<OrderCoupon, "serviceKind" | "planSlug">, ctx: Pick<OrderContext, "serviceKind" | "planSlug">): boolean {
  if (coupon.serviceKind !== "ANY" && coupon.serviceKind !== ctx.serviceKind) return false;
  if (coupon.planSlug && coupon.planSlug.toLowerCase() !== ctx.planSlug.toLowerCase()) return false;
  return true;
}

export type CouponOrderVerdict =
  | { ok: true; discountCents: number; label: string }
  | { ok: false; error: string };

/** "1 month free on Starter", "20% off (first 1 month)", "$5.00 off"… */
function describe(coupon: Pick<OrderCoupon, "kind" | "value">, cappedMonths: number, termMonths: number): string {
  const monthNote = cappedMonths < termMonths ? ` (first ${cappedMonths} month${cappedMonths === 1 ? "" : "s"})` : "";
  switch (coupon.kind) {
    case "PERCENT":
      return coupon.value >= 100 ? `${cappedMonths} month${cappedMonths === 1 ? "" : "s"} free` : `${coupon.value}% off${monthNote}`;
    case "FIXED_CENTS":
      return `$${(coupon.value / 100).toFixed(2)} off`;
    default:
      return "discount";
  }
}

